// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.detectionimport com.google.mlkit.vision.common.InputImageimport com.google.mlkit.vision.objects.ObjectDetectionimport com.google.mlkit.vision.objects.ObjectDetector as MlKitObjectDetectorClientimport com.google.mlkit.vision.objects.defaults.ObjectDetectorOptionsimport com.roshan.persona.vision.ocr.BoundingBoximport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.toBitmapimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — ML Kit Object Detector (Module 6 v4 — Step 6.1, REAL implementation). * * Wraps `com.google.mlkit:object-detection` for on-device object detection. * Implements [SsdModelDelegate] so it slots into the same Hilt graph as the * (hypothetical) TFLite SSD delegate. * * ## Performance * *  - < 80 ms per frame on mid-range devices (ML Kit on-device, default model). *  - Real-time: 10-15 FPS detection. *  - Returns up to 5 detected objects per frame (ML Kit default). * * ## Class mapping * * ML Kit's default object detector returns bounding boxes WITHOUT class * labels (only "object" + confidence). When [SsdModelDelegate.supportedClasses] * is queried, we return the COCO-80 [DetectionClass] list so downstream * consumers (NMS, tracker, UI) can still classify by classId when a richer * detector (TFLite SSD) is wired. * * @see <a href="https://developers.google.com/ml-kit/vision/object-detection/android">ML Kit Object Detection</a> */@Singletonclass MlKitObjectDetector @Inject constructor() : SsdModelDelegate {    private val detector: MlKitObjectDetectorClient = ObjectDetection.getClient(        ObjectDetectorOptions.Builder()            .setDetectorMode(ObjectDetectorOptions.SINGLE_IMAGE_MODE)            .enableMultipleObjects()            .enableClassification()  // Best-effort — may still return "unknown" class.            .build(),    )    @Volatile    private var ready: Boolean = true    override suspend fun detect(frame: RgbImage): List<DetectedObject> {        if (!ready || frame.width <= 0 || frame.height <= 0) return emptyList()        val bitmap = try {            frame.toBitmap()        } catch (t: Throwable) {            Timber.tag("NOUS.Vision").e(t, "Failed to convert RgbImage to Bitmap")            return emptyList()        }        return try {            val inputImage = InputImage.fromBitmap(bitmap, 0)            // Tasks.await with timeout — if Google Play Services is unresponsive,            // we don't hang forever (which would cause ANR). 10 seconds is the            // max we'll wait for ML Kit object detection on a single frame.            val mlObjects = com.google.android.gms.tasks.Tasks.await(                detector.process(inputImage),                10,                java.util.concurrent.TimeUnit.SECONDS,            )            val width = frame.width.toFloat().coerceAtLeast(1f)            val height = frame.height.toFloat().coerceAtLeast(1f)            mlObjects.mapNotNull { obj ->                val rect = obj.boundingBox ?: return@mapNotNull null                val left = (rect.left.toFloat() / width).coerceIn(0f, 0.999f)                val top = (rect.top.toFloat() / height).coerceIn(0f, 0.999f)                val right = (rect.right.toFloat() / width).coerceIn(left + 0.001f, 1f)                val bottom = (rect.bottom.toFloat() / height).coerceIn(top + 0.001f, 1f)                val boundingBox = try {                    BoundingBox(left = left, top = top, right = right, bottom = bottom)                } catch (iae: IllegalArgumentException) {                    Timber.tag("NOUS.Vision").w(iae, "Skipping object with invalid bbox: $rect")                    return@mapNotNull null                }                // ML Kit returns labels via `labels` list (when classification is enabled).                // Use the first label if available, else "object".                val classLabel = obj.labels.firstOrNull()?.text ?: "object"                val confidence = obj.labels.firstOrNull()?.confidence ?: 0.8f                DetectedObject(                    classLabel = classLabel,                    classId = DetectionClass.fromLabel(classLabel).classId,                    confidence = confidence,                    boundingBox = boundingBox,                    trackId = null,                )            }        } catch (t: Throwable) {            Timber.tag("NOUS.Vision").e(t, "ML Kit ObjectDetection failed")            emptyList()        } finally {            bitmap.recycle()        }    }    override fun isReady(): Boolean = ready    override fun supportedClasses(): List<DetectionClass> = DetectionClass.COCO_CLASSES}
